function buildCatConfig(meta){return{id:meta.id,name:meta.name,icon:meta.icon||'wallet',budget:Number(meta.budget||0)}}
function cloudSavingsSource(src){return 'manual'}
function encodeSavingsNote(note,src){note=String(note||'');if(!src||src==='manual'||note.indexOf('[[okane_source:')>=0)return note;return '[[okane_source:'+src+']]'+note}
function decodeSavingsSource(src,note){var m=String(note||'').match(/^\[\[okane_source:([a-z_]+)\]\]/);return m?m[1]:(src||'manual')}
function decodeSavingsNote(note){return String(note||'').replace(/^\[\[okane_source:[a-z_]+\]\]/,'')}
function iconSvgByKey(iconKey,fallbackKey){
    if(iconKey&&ICON_LIST[iconKey])return ICON_LIST[iconKey];
    if(iconKey&&IC[iconKey])return IC[iconKey];
    if(fallbackKey&&IC[fallbackKey])return IC[fallbackKey];
    return IC.other
}
function hasLegacyUsageInStore(s,id){
    if(s.mo)for(var mk0 in s.mo){var mo=s.mo[mk0]||{};if(Number(mo[id]||0)>0)return true}
    if(s.dLog)for(var dk in s.dLog){if((s.dLog[dk]||[]).some(function(x){return (x.cat||'other')===id}))return true}
    if((s.recur||[]).some(function(x){return (x.cat||'other')===id}))return true;
    return false
}
function ensureCategoryCatalog(){
    var s=gs(),cats=s.customCats||[],changed=false;
    Object.keys(LEGACY_CATS).forEach(function(id){
        if(cats.some(function(cat){return cat.id===id}))return;
        if(!hasLegacyUsageInStore(s,id))return;
        cats.push(buildCatConfig(LEGACY_CATS[id]));
        changed=true
    });
    if(changed){s.customCats=cats;persistStore(s,false)}
    return s.customCats||[]
}
function gCats(){return ensureCategoryCatalog()}
function getBudgetKeys(d){return Object.keys(d||{}).filter(function(k){return !CAT_RESERVED_KEYS[k]&&typeof d[k]!=='object'})}
function gm(y,m){
    var s=gs(),k=mk(y,m);
    if(!s.mo)s.mo={};
    var autoCreated=false;
    if(!s.mo[k]){
        var st=gSet();
        var obj={sal:Number(st.salary||0),savAutoTransfer:false,oI:[]};
        gCats().forEach(function(c){obj[c.id]=Number(c.budget||0)});
        s.mo[k]=obj;
        autoCreated=true
    }
    var d=s.mo[k];
    if(!d.oI)d.oI=[];
    if(!Array.isArray(d.oI))d.oI=[];
    d.oI=d.oI.map(function(item){
        item=item||{};
        return{id:item.id||genId('inc'),a:Number(item.a||0),n:String(item.n||''),ck:item.ck!==false}
    });
    // Return a view with shopee merged from s.shM (source of truth). Do not persist the shopee field.
    var view=Object.assign({},d);
    if(gSh(y,m)>0||d.shopee!==undefined||gCats().some(function(cat){return cat.id==='shopee'}))view.shopee=gSh(y,m);
    if(autoCreated){/* don't persist on read-only auto-create */}
    return view
}
function sm_(y,m,d){var s=gs();if(!s.mo)s.mo={};var out=Object.assign({},d);delete out.shopee;s.mo[mk(y,m)]=out;syncNow(s)}
function computeSavingsBalance(history){var bal=0;(history||[]).forEach(function(h){var amt=Number(h.amount||0);if(h.type==='withdraw')bal=Math.max(0,bal-amt);else bal+=amt});return bal}
function getSavings(){var s=gs();if(!s.savings)s.savings={balance:0,history:[]};var hist=s.savings.history||[];return{balance:computeSavingsBalance(hist),history:hist}}
function refreshCurrentContext(){var prevMonthKey=mk(NOW.getFullYear(),NOW.getMonth()),prevDayKey=dKey(NOW),now=getBangkokNow();if(mk(cY,sM_)===prevMonthKey){cY=now.getFullYear();sM_=now.getMonth()}if(dKey(viewDate)===prevDayKey)viewDate=new Date(now);NOW=now}
function isP(y,m){var now=getBangkokNow();return y<now.getFullYear()||(y===now.getFullYear()&&m<now.getMonth())}
function fmt(n){var s=gs();var showDec=s.settings&&s.settings.showDecimal!==undefined?s.settings.showDecimal:true;if(showDec)return Number(n||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});return Number(n||0).toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:2})}
function fmtSh(n){var v=Math.abs(Number(n||0));if(v>=1e6)return(v/1e6).toFixed(1)+'M';if(v>=1e4)return(v/1000).toFixed(0)+'K';if(v>=1000)return(v/1000).toFixed(1)+'K';return String(Math.round(v))}
function esc(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML}
function hexToRgba(hex, alpha) {
    if (!hex || hex.charAt(0) !== '#') return 'rgba(128,128,128,' + alpha + ')';
    var r = parseInt(hex.slice(1,3), 16), g = parseInt(hex.slice(3,5), 16), b = parseInt(hex.slice(5,7), 16);
    return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
}
function dKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function sanitizeNumericValue(val,allowDecimal){
    var raw=String(val==null?'':val).replace(/,/g,'');
    if(!allowDecimal)return raw.replace(/\D/g,'');
    raw=raw.replace(/[^0-9.]/g,'');
    var firstDot=raw.indexOf('.');
    if(firstDot<0)return raw;
    return raw.slice(0,firstDot+1)+raw.slice(firstDot+1).replace(/\./g,'')
}
function shouldUseIntegerInput(el){
    var id=String((el&&el.id)||'');
    return id==='pinInput'||id==='stWarnPct'||id==='stCycle'||id==='stDue'||id==='simMonthsCustom'||/^sh\d+$/.test(id)
}
function enhanceNumericInputs(root){
    root=root||document;
    if(!root||!root.querySelectorAll)return;
    root.querySelectorAll('input[type="number"], #pinInput, .edit-val, .si').forEach(function(el){
        var integerOnly=shouldUseIntegerInput(el);
        if(el.id==='pinInput'){
            el.setAttribute('inputmode','numeric');
            el.setAttribute('pattern','[0-9]*');
            el.setAttribute('autocomplete','one-time-code');
            return
        }
        el.setAttribute('inputmode',integerOnly?'numeric':'decimal');
        el.setAttribute('pattern',integerOnly?'[0-9]*':'[0-9]*[.]?[0-9]*');
        el.setAttribute('autocomplete','off');
        if(!el._focusClearBound){
            el._focusClearBound=true;
            el.addEventListener('focus',function(){if(this.value==='0'||this.value==='0.00'||this.value==='0.0')this.value=''});
            el.addEventListener('blur',function(){if(this.value==='')this.value='0'})
        }
    })
}
function guardNumericInput(el){
    if(!el)return;
    var integerOnly=shouldUseIntegerInput(el);
    var next=sanitizeNumericValue(el.value,!integerOnly);
    if(el.value!==next)el.value=next
}
function getDayLog(ds){var s=gs();return(s.dLog&&s.dLog[ds])?JSON.parse(JSON.stringify(s.dLog[ds])):[]}
function saveDayLog(ds,arr){var s=gs();if(!s.dLog)s.dLog={};s.dLog[ds]=arr;syncNow(s)}
function getDailySpent(y,m,catId){var s=gs(),total=0,prefix=mk(y,m);if(!s.dLog)return 0;Object.keys(s.dLog).forEach(function(dk){if(dk.startsWith(prefix)){s.dLog[dk].forEach(function(x){if(x.cat===catId)total+=Number(x.a||0)})}});return total}
function getDailyOther(y,m){var s=gs(),items=[],prefix=mk(y,m);if(!s.dLog)return items;Object.keys(s.dLog).sort().forEach(function(dk){if(dk.startsWith(prefix)){s.dLog[dk].forEach(function(x){if(x.cat==='other')items.push(Object.assign({date:dk},x))})}});return items}
function getDailyOtherTotal(y,m){return getDailyOther(y,m).reduce(function(s,x){return s+Number(x.a||0)},0)}
function getSavingsTransferFromRemaining(y,m){var sav=getSavings();var mk2=mk(y,m);return sav.history.filter(function(h){return h.monthKey===mk2&&h.type==='add'&&h.source==='remaining'}).reduce(function(s,h){return s+Number(h.amount||0)},0)}
function getWallets(){var s=gs();if(!s.wallets||s.wallets.length===0){s.wallets=[{id:'cash',name:'เงินสด',type:'cash'},{id:'bank',name:'บัญชี',type:'bank'},{id:'card',name:'บัตร',type:'card'}];persistStore(s,false)}return s.wallets}
function getWalletName(id){var w=getWallets().find(function(x){return x.id===id});return w?w.name:id}
function getLastWallet(){var s=gs();return s.lastWallet||'cash'}
function setLastWallet(id){var s=gs();s.lastWallet=id;syncNow(s)}
function genId(p){return (p||'id')+'_'+Date.now()+'_'+Math.random().toString(16).slice(2)}
function addTombstone(s,col,id){if(!s._tombstones)s._tombstones={};if(!s._tombstones[col])s._tombstones[col]={};s._tombstones[col][id]=Date.now();return s}
function genSalt(){return Math.random().toString(16).slice(2)+Math.random().toString(16).slice(2)}
function applySessionData(d){d=normalizeStore(d);d.isLoggedIn=true;d.userInfo=userInfo;return d}
function sha256Hex(str){if(!(window.crypto&&crypto.subtle))return Promise.resolve(btoa(unescape(encodeURIComponent(str))).slice(0,64));var enc=new TextEncoder().encode(str);return crypto.subtle.digest('SHA-256',enc).then(function(buf){var h='',v=new Uint8Array(buf);for(var i=0;i<v.length;i++)h+=v[i].toString(16).padStart(2,'0');return h})}
function getPinCfg(){var s=gs();return s.pin||{enabled:false,hash:'',salt:''}}
function setPinCfg(p){var s=gs();s.pin=p;syncNow(s)}
function pinEnabled(){return !!getPinCfg().enabled}
function showPinLock(mode,sub){_pinMode=mode;_pinValue='';_pinPending=sub||null;var el=document.getElementById('pinLock');if(!el)return;document.getElementById('pinSub').textContent=_pinPending&&_pinPending.sub?_pinPending.sub:'เพื่อความปลอดภัยของข้อมูล';document.querySelector('#pinLock .pin-title').textContent=_pinPending&&_pinPending.title?_pinPending.title:'ใส่ PIN เพื่อปลดล็อก';var cbtn=document.querySelector('#pinLock .pin-actions .btn-gh');if(cbtn)cbtn.style.display=(_pinPending&&_pinPending.canCancel===false)?'none':'';document.getElementById('pinInput').value='';updatePinDots();el.classList.add('show');setTimeout(function(){var i=document.getElementById('pinInput');if(i)i.focus()},50)}
function hidePinLock(){var el=document.getElementById('pinLock');if(el)el.classList.remove('show')}
function updatePinDots(){var d=document.getElementById('pinDots');if(!d)return;var sp=d.querySelectorAll('span');for(var i=0;i<sp.length;i++){if(i<_pinValue.length)sp[i].classList.add('on');else sp[i].classList.remove('on')}}
function onPinInput(v){_pinValue=String(v||'').replace(/\D/g,'').slice(0,6);var i=document.getElementById('pinInput');if(i&&i.value!==_pinValue)i.value=_pinValue;updatePinDots();if((_pinPending&&_pinPending.autoSubmit)&&_pinValue.length>=(_pinPending.len||4))pinSubmit()}
function pinCancel(){if(_pinPending&&_pinPending.canCancel===false)return;hidePinLock()}
function pinSubmit(){
    var val=_pinValue;
    var cfg=getPinCfg();
    var len=_pinPending&&_pinPending.len?_pinPending.len:4;
    if(val.length<len)return;
    val=val.slice(0,len);
    if(_pinMode==='unlock'){
        sha256Hex(val+cfg.salt).then(function(h){
            if(h===cfg.hash){
                var s=gs();if(!s.pin)s.pin=cfg;s.pin.lastUnlock=Date.now();syncNow(s);hidePinLock();render()
            }else{
                _pinValue='';var i=document.getElementById('pinInput');if(i)i.value='';updatePinDots();document.getElementById('pinSub').textContent='PIN ไม่ถูกต้อง'
            }
        });
        return
    }
    if(_pinMode==='set'){
        var salt=genSalt();
        sha256Hex(val+salt).then(function(h){
            setPinCfg({enabled:true,hash:h,salt:salt,lastUnlock:Date.now()});
            hidePinLock();
            renderSettings()
        });
        return
    }
    if(_pinMode==='disable'){
        sha256Hex(val+cfg.salt).then(function(h){
            if(h===cfg.hash){
                setPinCfg({enabled:false,hash:'',salt:''});
                hidePinLock();
                renderSettings()
            }else{
                _pinValue='';var i=document.getElementById('pinInput');if(i)i.value='';updatePinDots();document.getElementById('pinSub').textContent='PIN ไม่ถูกต้อง'
            }
        });
        return
    }
    if(_pinMode==='change_old'){
        sha256Hex(val+cfg.salt).then(function(h){
            if(h===cfg.hash){
                showPinLock('change_new',{title:'ตั้ง PIN ใหม่',sub:'ใส่ PIN ใหม่ 4 หลัก',len:4,autoSubmit:true,canCancel:false})
            }else{
                _pinValue='';var i=document.getElementById('pinInput');if(i)i.value='';updatePinDots();document.getElementById('pinSub').textContent='PIN ไม่ถูกต้อง'
            }
        });
        return
    }
    if(_pinMode==='change_new'){
        var salt2=genSalt();
        sha256Hex(val+salt2).then(function(h){
            setPinCfg({enabled:true,hash:h,salt:salt2,lastUnlock:Date.now()});
            hidePinLock();
            renderSettings()
        });
        return
    }
}

function getCatMeta(catId){
    var cat=gCats().find(function(x){return x.id===catId});
    if(cat)return Object.assign({},buildCatConfig(cat));
    if(getLegacyCat(catId))return buildCatConfig(getLegacyCat(catId));
    if(getPresetCat(catId))return buildCatConfig(getPresetCat(catId));
    return{id:catId,name:catId,icon:'wallet',budget:0}
}
function getCatIcon(catId){
    var meta=getCatMeta(catId);
    return iconSvgByKey(meta.icon,catId)
}
function catBadge(catId){return '<div class="ri custom cat-fixed-badge">'+getCatIcon(catId)+'</div>'}
function secTitle(svg,label,meta){
    return '<span class="sec-label'+(meta&&meta.editing?' editing':'')+'"><span class="sec-label-ic">'+svg+'</span><span>'+label+'</span></span>'
}
function incomeIconImg(cls){
    return '<img class="'+(cls||'income-wallet-img')+'" src="./assets/income-wallet.svg" alt="" aria-hidden="true">';
}
function glyphIcon(svg,cls){return '<span class="'+(cls||'glyph-icon')+'">'+svg+'</span>'}
function isNewUser(){
    var s=gs();
    if((s.customCats||[]).length>0)return false;
    if(s.mo&&Object.keys(s.mo).some(function(k){
        var d=s.mo[k]||{};
        if(Number(d.sal||0)>0)return true;
        if((d.oI||[]).length>0)return true;
        return getBudgetKeys(d).some(function(catId){return Number(d[catId]||0)>0})
    }))return false;
    if(s.dLog&&Object.keys(s.dLog).some(function(k){return (s.dLog[k]||[]).length>0}))return false;
    if((s.recur||[]).length>0)return false;
    if(s.savings&&Array.isArray(s.savings.history)&&s.savings.history.length>0)return false;
    if(s.shM&&Object.keys(s.shM).some(function(k){return Number(s.shM[k]||0)>0}))return false;
    if((s.goals||[]).length>0)return false;
    if((s.templates||[]).length>0)return false;
    return true
}
function activeCategoryIdsForMonth(d,y,m,spentMap,recurMap){
    var ids={};
    gCats().forEach(function(cat){ids[cat.id]=true});
    getBudgetKeys(d).forEach(function(id){if(Number(d[id]||0)>0)ids[id]=true});
    var sm=spentMap||getSpentMap(y,m);
    var rm=recurMap||getRecurringMap(y,m);
    Object.keys(sm).forEach(function(id){if(id!=='other')ids[id]=true});
    Object.keys(rm).forEach(function(id){if(id!=='other')ids[id]=true});
    return Object.keys(ids)
}

/* ===== AUTH ===== */
function updateSyncIndicator(){
    var el=document.getElementById('syncPendingBadge');
    if(el) {
        el.style.display=(!isGuest&&supabaseUserId&&_syncPending)?'':'none';
    }
    
    var ledWrap = document.getElementById('syncLedWrap');
    if (ledWrap) ledWrap.style.display = 'none';
    
    var btn = document.getElementById('userBtn');
    if (!btn) return;
    btn.classList.remove('sync-online','sync-cd329f3d3e55ddbcdc5485e272826d7653df873c','sync-offline');
    if (!isGuest && supabaseUserId) {
        if (!window.navigator.onLine) {
            btn.classList.add('sync-offline');
            btn.title = 'ไม่มีการเชื่อมต่อเครือข่าย';
        } else if (_syncing || _syncPending) {
            btn.classList.add('sync-cd329f3d3e55ddbcdc5485e272826d7653df873c');
            btn.title = _lastSyncError ? ('ยังบันทึกไม่สำเร็จ: ' + _lastSyncError) : 'กำลังอัปเดตข้อมูลไปยังระบบคลาวด์...';
        } else {
            btn.classList.add('sync-online');
            btn.title = 'เชื่อมต่อและซิงค์ข้อมูลกับคลาวด์เรียบร้อย';
        }
    }
}
window.addEventListener('online', updateSyncIndicator);
window.addEventListener('offline', updateSyncIndicator);
function finishAuth(syncLocal){
    isGuest=false;
    _authRefreshStarted=false;
    persistStore(applySessionData(gs()),false);
    if(syncLocal||_syncPending){_syncPending=false;queueSync(true)}
    if(_cd329f3d3e55ddbcdc5485e272826d7653df873cManualSync){_cd329f3d3e55ddbcdc5485e272826d7653df873cManualSync=false;setTimeout(manualSync,500)}
    updateSyncIndicator();
    if(document.getElementById('app').classList.contains('show')){updateUserBtn();render();return}
    enterApp()
}
function authRedirectTo(){return window.location.origin + window.location.pathname}
function setAuthMsg(msg,type){
    var el=document.getElementById('authMsg');
    if(!el)return;
    el.textContent=msg||'';
    el.className='auth-msg'+(type?' '+type:'');
}
function setAuthBusy(on){
    _authBusy=!!on;
    ['authPrimaryBtn','authGoogleBtn','authResetBtn','authOpenSigninBtn','authSwitchBtn'].forEach(function(id){
        var el=document.getElementById(id);
        if(el)el.disabled=_authBusy;
    });
    var btn=document.getElementById('authPrimaryBtn');
    if(btn)btn.textContent=_authBusy?'กำลังดำเนินการ...':(_authMode==='signup'?'สมัครสมาชิก':(_authMode==='recovery'?'ตั้งรหัสผ่านใหม่':'เข้าสู่ระบบ'));
}
function setAuthMode(mode){
    _authMode=(mode==='signin'||mode==='signup'||mode==='recovery')?mode:'landing';
    var landing=document.getElementById('authLanding'),panel=document.getElementById('authPanel');
    var card=document.querySelector('.auth-card');
    var title=document.getElementById('authPanelTitle'),sub=document.getElementById('authPanelSub');
    var nameRow=document.getElementById('authNameRow'),emailRow=document.getElementById('authEmailRow');
    var passRow=document.getElementById('authPasswordRow'),confirmRow=document.getElementById('authConfirmRow');
    var pass=document.getElementById('authPassword'),confirm=document.getElementById('authConfirm');
    var primary=document.getElementById('authPrimaryBtn'),reset=document.getElementById('authResetBtn'),switchBtn=document.getElementById('authSwitchBtn');
    if(landing)landing.classList.toggle('is-hidden',_authMode!=='landing');
    if(panel)panel.classList.toggle('is-hidden',_authMode==='landing');
    if(card)card.classList.toggle('is-panel-mode',_authMode!=='landing');
    if(title)title.textContent=_authMode==='signup'?'สมัครสมาชิก':(_authMode==='recovery'?'ตั้งรหัสผ่านใหม่':'เข้าสู่ระบบ');
    if(sub)sub.textContent=_authMode==='signup'?'สร้างบัญชี Okane ด้วยอีเมลของคุณ':(_authMode==='recovery'?'กรอกรหัสผ่านใหม่สำหรับบัญชีนี้':'เข้าใช้งานด้วยอีเมลและรหัสผ่าน');
    if(nameRow)nameRow.classList.toggle('is-hidden',_authMode!=='signup');
    if(emailRow)emailRow.classList.toggle('is-hidden',_authMode==='recovery');
    if(passRow)passRow.classList.toggle('is-hidden',false);
    if(confirmRow)confirmRow.classList.toggle('is-hidden',_authMode==='signin');
    if(pass){
        pass.autocomplete=_authMode==='signin'?'current-password':'new-password';
        pass.placeholder=_authMode==='signin'?'รหัสผ่านของคุณ':'ตัวใหญ่ 1 ตัว และตัวเลขอย่างน้อย 4 ตัว';
    }
    if(confirm)confirm.autocomplete='new-password';
    if(primary)primary.textContent=_authMode==='signup'?'สมัครสมาชิก':(_authMode==='recovery'?'ตั้งรหัสผ่านใหม่':'เข้าสู่ระบบ');
    if(reset)reset.style.display=_authMode==='signin'?'inline-flex':'none';
    if(switchBtn){
        switchBtn.style.display=_authMode==='recovery'?'none':'inline-flex';
        switchBtn.textContent=_authMode==='signup'?'มีบัญชีอยู่แล้ว? เข้าสู่ระบบ':'ยังไม่มีบัญชี? สมัครสมาชิกก่อน';
    }
    setAuthMsg('', '');
}
function authEnter(e){if(e&&e.key==='Enter')emailAuthSubmit()}
function openAuthSignup(){
    var w=document.getElementById('welcome');
    if(w)w.classList.remove('hide');
    setAuthMode('signup');
    setTimeout(function(){var el=document.getElementById('authName')||document.getElementById('authEmail');if(el)el.focus()},50);
}
function openAuthSignin(){
    var w=document.getElementById('welcome');
    if(w)w.classList.remove('hide');
    setAuthMode('signin');
    setTimeout(function(){var el=document.getElementById('authEmail');if(el)el.focus()},50);
}
function showPasswordRecovery(){
    var w=document.getElementById('welcome');
    if(w)w.classList.remove('hide');
    setAuthMode('recovery');
    setAuthMsg('ตั้งรหัสผ่านใหม่สำหรับบัญชีของคุณ', 'info');
    setTimeout(function(){var el=document.getElementById('authPassword');if(el)el.focus()},50);
}
function getAuthInput(){
    return {
        name:((document.getElementById('authName')||{}).value||'').trim(),
        email:((document.getElementById('authEmail')||{}).value||'').trim().toLowerCase(),
        password:((document.getElementById('authPassword')||{}).value||''),
        confirm:((document.getElementById('authConfirm')||{}).value||'')
    }
}
function validateNewPassword(password){
    var p=String(password||'');
    if(p.length<6)return 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร';
    if(!/[A-Z]/.test(p))return 'รหัสผ่านต้องมีตัวอักษรภาษาอังกฤษตัวพิมพ์ใหญ่อย่างน้อย 1 ตัว';
    var digitCount=(p.match(/\d/g)||[]).length;
    if(digitCount<4)return 'รหัสผ่านต้องมีตัวเลขอย่างน้อย 4 ตัว';
    return '';
}
async function emailAuthSubmit(){
    if(_authBusy)return;
    if(_authMode==='landing'){setAuthMode('signin');return}
    if(!supabase){setAuthMsg('ไม่พบการเชื่อมต่อ Supabase', 'error');return}
    var v=getAuthInput();
    if(_authMode!=='recovery'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)){setAuthMsg('กรุณากรอกอีเมลให้ถูกต้อง', 'error');return}
    if(_authMode==='signin'&&v.password.length<1){setAuthMsg('กรุณากรอกรหัสผ่าน', 'error');return}
    if(_authMode==='signup'||_authMode==='recovery'){
        var passError=validateNewPassword(v.password);
        if(passError){setAuthMsg(passError, 'error');return}
        if(v.password!==v.confirm){setAuthMsg('รหัสผ่านทั้งสองช่องไม่ตรงกัน', 'error');return}
    }
    setAuthBusy(true);
    try{
        var resp;
        if(_authMode==='signup'){
            resp=await supabase.auth.signUp({
                email:v.email,
                password:v.password,
                options:{emailRedirectTo:authRedirectTo(),data:{full_name:v.name||v.email.split('@')[0]}}
            });
            if(resp.error)throw resp.error;
            if(resp.data&&resp.data.session)setAuthMsg('สมัครสำเร็จ กำลังเปิดกระเป๋าของคุณ...', 'ok');
            else setAuthMsg('ส่งอีเมลยืนยันแล้ว กรุณายืนยันบัญชีก่อนเข้าสู่ระบบ', 'ok');
        }else if(_authMode==='recovery'){
            resp=await supabase.auth.updateUser({password:v.password});
            if(resp.error)throw resp.error;
            setAuthMsg('ตั้งรหัสผ่านใหม่เรียบร้อยแล้ว', 'ok');
            setTimeout(function(){finishAuth(true)},500);
        }else{
            resp=await supabase.auth.signInWithPassword({email:v.email,password:v.password});
            if(resp.error)throw resp.error;
            setAuthMsg('เข้าสู่ระบบสำเร็จ กำลังซิงค์ข้อมูล...', 'ok');
        }
    }catch(e){
        setAuthMsg(authFriendlyError(e&&e.message?e.message:String(e)), 'error');
    }finally{
        setAuthBusy(false);
    }
}
async function resetPasswordEmail(){
    if(_authBusy)return;
    if(!supabase){setAuthMsg('ไม่พบการเชื่อมต่อ Supabase', 'error');return}
    var email=((document.getElementById('authEmail')||{}).value||'').trim().toLowerCase();
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){setAuthMsg('กรอกอีเมลก่อน แล้วผมจะส่งลิงก์ตั้งรหัสผ่านใหม่ให้', 'error');return}
    setAuthBusy(true);
    try{
        var resp=await supabase.auth.resetPasswordForEmail(email,{redirectTo:authRedirectTo()});
        if(resp.error)throw resp.error;
        setAuthMsg('ส่งลิงก์ตั้งรหัสผ่านใหม่ไปที่อีเมลแล้ว', 'ok');
    }catch(e){
        setAuthMsg(authFriendlyError(e&&e.message?e.message:String(e)), 'error');
    }finally{
        setAuthBusy(false);
    }
}
function authFriendlyError(msg){
    var m=String(msg||'');
    if(/invalid login credentials/i.test(m))return 'อีเมลหรือรหัสผ่านไม่ถูกต้อง';
    if(/email not confirmed/i.test(m))return 'กรุณายืนยันอีเมลก่อนเข้าสู่ระบบ';
    if(/user already registered|already been registered/i.test(m))return 'อีเมลนี้ถูกสมัครไว้แล้ว ลองเข้าสู่ระบบแทน';
    if(/password/i.test(m)&&/short|weak/i.test(m))return 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร มีตัวพิมพ์ใหญ่ 1 ตัว และมีตัวเลขอย่างน้อย 4 ตัว';
    return m||'เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง';
}
function consumeAdminOAuthReturn(){
    try{
        var url=sessionStorage.getItem('okane_admin_oauth');
        if(!url)return false;
        sessionStorage.removeItem('okane_admin_oauth');
        window.location.replace(url);
        return true;
    }catch(e){return false}
}
function initSupabaseAuth() {
    supabase.auth.onAuthStateChange(function(event, session) {
        if (session) {
            supabaseUserId = session.user.id;
            isGuest = false;
            var md=session.user.user_metadata||{};
            var appMd=session.user.app_metadata||{};
            var email=session.user.email||'';
            var provider=appMd.provider||((appMd.providers&&appMd.providers[0])||'email');
            userInfo = {
                name: md.full_name || md.name || (email?email.split('@')[0]:'User'),
                email: email,
                picture: md.avatar_url || md.picture || '',
                provider: provider
            };
            if(event==='PASSWORD_RECOVERY'){showPasswordRecovery();return}
            if(consumeAdminOAuthReturn())return;
            checkAndHandleMigration(supabaseUserId).then(function() {
                finishAuth(false);
            });
        } else {
            supabaseUserId = null;
            isGuest = true;
            userInfo = { name: '', email: '', picture: '', provider: '' };
            
            // Stay locked on welcome screen, hide app
            document.getElementById('welcome').classList.remove('hide');
            document.getElementById('app').classList.remove('show');
            setAuthMode('landing');
        }
    });
}
function googleLogin(){
    supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
            redirectTo: window.location.origin + window.location.pathname
        }
    });
}
function fetchUserInfo(){
    return Promise.resolve();
}
async function syncLocalToSupabase(userId) {
    if (!userId) return;
    var s = gs();
    ensureCategoryCatalog();
    s = gs();
    function ok(resp, label){if(resp&&resp.error)throw new Error(label + ': ' + resp.error.message)}
    function safeNumber(v, fallback){var n=Number(v);return Number.isFinite(n)?n:fallback}
    
    var profileRow = {
        id: userId,
        email: userInfo.email || null,
        display_name: (s.userName || userInfo.name || ''),
        avatar_url: getSafeImageSrc(s.customPicture || userInfo.picture || '') || null,
        auth_provider: userInfo.provider || 'email',
        salary: safeNumber(s.settings ? s.settings.salary : 0, 0),
        savings_goal: safeNumber(s.settings ? s.settings.savGoal : 0, 0),
        show_decimal: s.settings ? !!s.settings.showDecimal : true,
        hide_amount: s.settings ? !!s.settings.hideAmount : false,
        low_remaining: safeNumber(s.settings ? s.settings.lowRemaining : 1000, 1000),
        warn_percent: safeNumber(s.settings ? s.settings.warnPercent : 90, 90),
        weekly_on: s.settings ? !!s.settings.weeklyOn : false,
        theme: s.theme || 'light',
        pin_enabled: s.pin ? !!s.pin.enabled : false,
        pin_hash: s.pin ? s.pin.hash || null : null,
        pin_salt: s.pin ? s.pin.salt || null : null,
        last_wallet: s.lastWallet || 'cash',
        updated_at: new Date().toISOString()
    };
    
    var wallets = s.wallets && s.wallets.length > 0 ? s.wallets : getWallets();
    var walletRows = wallets.map(function(w) {
        return { user_id: userId, id: w.id, name: w.name, type: w.type || 'cash' };
    });
    
    var categoryRows = (s.customCats || []).map(function(c) {
        return { user_id: userId, id: c.id, name: c.name, icon: c.icon || 'wallet', color: UI_CAT_COLOR, budget: Number(c.budget || 0) };
    });
    
    var localMonthKeys = Object.keys(s.mo || {});
    var budgetRows = localMonthKeys.map(function(k) {
        return {
            user_id: userId,
            month_key: k,
            salary: Number(s.mo[k].sal || 0),
            savings_auto_transfer: !!s.mo[k].savAutoTransfer,
            updated_at: new Date().toISOString()
        };
    });
    
    var catBudgetRows = [];
    var incomeRows = [];
    localMonthKeys.forEach(function(k) {
        var d = s.mo[k];
        getBudgetKeys(d).forEach(function(catId) {
            catBudgetRows.push({
                user_id: userId,
                month_key: k,
                category_id: catId,
                budget_amount: Number(d[catId] || 0)
            });
        });
        (d.oI || []).forEach(function(item) {
            incomeRows.push({
                user_id: userId,
                id: item.id || genId('inc'),
                month_key: k,
                amount: Number(item.a || 0),
                note: String(item.n || ''),
                color: UI_INCOME_COLOR,
                is_checked: item.ck !== false
            });
        });
    });
    
    var txRows = [];
    Object.keys(s.dLog || {}).forEach(function(dk) {
        (s.dLog[dk] || []).forEach(function(tx) {
            txRows.push({
                user_id: userId,
                id: tx.id || genId('dl'),
                date_key: dk,
                amount: Number(tx.a || 0),
                category_id: tx.cat || 'other',
                note: String(tx.n || ''),
                wallet_id: tx.w || 'cash',
                time_key: tx.t || '12:00'
            });
        });
    });
    
    var savRows = ((s.savings && s.savings.history) || []).map(function(item) {
        return {
            user_id: userId,
            id: item.id || genId('sv'),
            type: item.type || 'add',
            amount: Number(item.amount || 0),
            date: item.date || new Date().toISOString(),
            month_key: item.monthKey || mk(new Date().getFullYear(), new Date().getMonth()),
            source: cloudSavingsSource(item.source || 'manual'),
            note: encodeSavingsNote(item.note,item.source)
        };
    });
    
    var activeShKeys = Object.keys(s.shM || {});
    var shRows = activeShKeys.map(function(k) {
        return { user_id: userId, month_key: k, amount: Number(s.shM[k] || 0) };
    });
    
    var recurRows = (s.recur || []).map(function(item) {
        return { user_id: userId, id: item.id, name: item.name, amount: Number(item.amount || 0), category_id: item.cat || 'other', is_on: item.on !== false };
    });
    
    var goalRows = (s.goals || []).map(function(item) {
        return { user_id: userId, id: item.id, name: item.name, target_amount: Number(item.target || 0), current_amount: Number(item.cur || 0) };
    });
    
    var tplRows = (s.templates || []).map(function(t) {
        return { user_id: userId, id: t.id, name: t.name, snapshot_data: t.snapshot || {} };
    });
    
    var globalIconMap = window.OkaneCMS ? OkaneCMS.data.icons : {};
    var activeIconKeys = Object.keys(s.customIcons || {}).filter(function(k) {
        return !window.OkaneCMS || OkaneCMS.shouldSyncUserIconKey(k, globalIconMap);
    });
    
    var iconRows = activeIconKeys.map(function(k) {
        return { user_id: userId, icon_key: k, svg_content: s.customIcons[k] };
    });

    // Fetch all existing IDs/keys from Supabase in parallel
    var fetchQueries = [
        supabase.from('wallets').select('id').eq('user_id', userId),
        supabase.from('categories').select('id').eq('user_id', userId),
        supabase.from('monthly_budgets').select('month_key').eq('user_id', userId),
        supabase.from('category_budgets').select('month_key, category_id').eq('user_id', userId),
        supabase.from('additional_income').select('id').eq('user_id', userId),
        supabase.from('transactions').select('id').eq('user_id', userId),
        supabase.from('savings_history').select('id').eq('user_id', userId),
        supabase.from('shopee_installments').select('month_key').eq('user_id', userId),
        supabase.from('recurring_expenses').select('id').eq('user_id', userId),
        supabase.from('savings_goals').select('id').eq('user_id', userId),
        supabase.from('budget_templates').select('id').eq('user_id', userId),
        supabase.from('custom_icons').select('icon_key').eq('user_id', userId)
    ];
    var fetched = await Promise.all(fetchQueries);
    for (var i = 0; i < fetched.length; i++) {
        if (fetched[i].error) throw new Error("Sync pre-fetch error: " + fetched[i].error.message);
    }

    var deleteQueries = [];
    
    // 1. wallets
    var remoteWalletIds = (fetched[0].data || []).map(function(x){return x.id});
    var localWalletIds = walletRows.map(function(x){return x.id});
    var delWallets = remoteWalletIds.filter(function(id){return localWalletIds.indexOf(id) === -1});
    if (delWallets.length > 0) deleteQueries.push(supabase.from('wallets').delete().eq('user_id', userId).in('id', delWallets));
    
    // 2. categories
    var remoteCatIds = (fetched[1].data || []).map(function(x){return x.id});
    var localCatIds = categoryRows.map(function(x){return x.id});
    var delCats = remoteCatIds.filter(function(id){return localCatIds.indexOf(id) === -1});
    if (delCats.length > 0) deleteQueries.push(supabase.from('categories').delete().eq('user_id', userId).in('id', delCats));
    
    // 3. monthly_budgets
    var remoteMonthKeys = (fetched[2].data || []).map(function(x){return x.month_key});
    var localMonthKeys = budgetRows.map(function(x){return x.month_key});
    var delMonths = remoteMonthKeys.filter(function(k){return localMonthKeys.indexOf(k) === -1});
    if (delMonths.length > 0) deleteQueries.push(supabase.from('monthly_budgets').delete().eq('user_id', userId).in('month_key', delMonths));
    
    // 4. category_budgets
    var remoteCatBudgets = fetched[3].data || [];
    var delCatBudgets = remoteCatBudgets.filter(function(rCb) {
        return !catBudgetRows.some(function(lCb) {
            return lCb.month_key === rCb.month_key && lCb.category_id === rCb.category_id;
        });
    });
    delCatBudgets.forEach(function(item) {
        deleteQueries.push(supabase.from('category_budgets').delete().eq('user_id', userId).eq('month_key', item.month_key).eq('category_id', item.category_id));
    });
    
    // 5. additional_income
    var remoteIncomeIds = (fetched[4].data || []).map(function(x){return x.id});
    var localIncomeIds = incomeRows.map(function(x){return x.id});
    var delIncome = remoteIncomeIds.filter(function(id){return localIncomeIds.indexOf(id) === -1});
    if (delIncome.length > 0) deleteQueries.push(supabase.from('additional_income').delete().eq('user_id', userId).in('id', delIncome));
    
    // 6. transactions
    var remoteTxIds = (fetched[5].data || []).map(function(x){return x.id});
    var localTxIds = txRows.map(function(x){return x.id});
    var delTx = remoteTxIds.filter(function(id){return localTxIds.indexOf(id) === -1});
    if (delTx.length > 0) deleteQueries.push(supabase.from('transactions').delete().eq('user_id', userId).in('id', delTx));
    
    // 7. savings_history
    var remoteSavIds = (fetched[6].data || []).map(function(x){return x.id});
    var localSavIds = savRows.map(function(x){return x.id});
    var delSav = remoteSavIds.filter(function(id){return localSavIds.indexOf(id) === -1});
    if (delSav.length > 0) deleteQueries.push(supabase.from('savings_history').delete().eq('user_id', userId).in('id', delSav));
    
    // 8. shopee_installments
    var remoteShKeys = (fetched[7].data || []).map(function(x){return x.month_key});
    var localShKeys = shRows.map(function(x){return x.month_key});
    var delSh = remoteShKeys.filter(function(k){return localShKeys.indexOf(k) === -1});
    if (delSh.length > 0) deleteQueries.push(supabase.from('shopee_installments').delete().eq('user_id', userId).in('month_key', delSh));
    
    // 9. recurring_expenses
    var remoteRecurIds = (fetched[8].data || []).map(function(x){return x.id});
    var localRecurIds = recurRows.map(function(x){return x.id});
    var delRecur = remoteRecurIds.filter(function(id){return localRecurIds.indexOf(id) === -1});
    if (delRecur.length > 0) deleteQueries.push(supabase.from('recurring_expenses').delete().eq('user_id', userId).in('id', delRecur));
    
    // 10. savings_goals
    var remoteGoalIds = (fetched[9].data || []).map(function(x){return x.id});
    var localGoalIds = goalRows.map(function(x){return x.id});
    var delGoals = remoteGoalIds.filter(function(id){return localGoalIds.indexOf(id) === -1});
    if (delGoals.length > 0) deleteQueries.push(supabase.from('savings_goals').delete().eq('user_id', userId).in('id', delGoals));
    
    // 11. budget_templates
    var remoteTplIds = (fetched[10].data || []).map(function(x){return x.id});
    var localTplIds = tplRows.map(function(x){return x.id});
    var delTpl = remoteTplIds.filter(function(id){return localTplIds.indexOf(id) === -1});
    if (delTpl.length > 0) deleteQueries.push(supabase.from('budget_templates').delete().eq('user_id', userId).in('id', delTpl));
    
    // 12. custom_icons
    var remoteIconKeys = (fetched[11].data || []).map(function(x){return x.icon_key});
    var localIconKeys = iconRows.map(function(x){return x.icon_key});
    var delIcons = remoteIconKeys.filter(function(k){return localIconKeys.indexOf(k) === -1});
    if (delIcons.length > 0) deleteQueries.push(supabase.from('custom_icons').delete().eq('user_id', userId).in('icon_key', delIcons));

    // Execute deletions in parallel
    if (deleteQueries.length > 0) {
        var deleteResults = await Promise.all(deleteQueries);
        for (var i = 0; i < deleteResults.length; i++) {
            if (deleteResults[i].error) throw new Error("Sync delete error: " + deleteResults[i].error.message);
        }
    }

    // Prepare and execute upserts in parallel
    var upsertQueries = [
        supabase.from('profiles').upsert([profileRow])
    ];
    if(walletRows.length > 0) upsertQueries.push(supabase.from('wallets').upsert(walletRows));
    if(categoryRows.length > 0) upsertQueries.push(supabase.from('categories').upsert(categoryRows));
    if(budgetRows.length > 0) upsertQueries.push(supabase.from('monthly_budgets').upsert(budgetRows));
    if(recurRows.length > 0) upsertQueries.push(supabase.from('recurring_expenses').upsert(recurRows));
    if(goalRows.length > 0) upsertQueries.push(supabase.from('savings_goals').upsert(goalRows));
    if(tplRows.length > 0) upsertQueries.push(supabase.from('budget_templates').upsert(tplRows));
    if(iconRows.length > 0) upsertQueries.push(supabase.from('custom_icons').upsert(iconRows));
    if(catBudgetRows.length > 0) upsertQueries.push(supabase.from('category_budgets').upsert(catBudgetRows));
    if(incomeRows.length > 0) upsertQueries.push(supabase.from('additional_income').upsert(incomeRows));
    if(txRows.length > 0) upsertQueries.push(supabase.from('transactions').upsert(txRows));
    if(savRows.length > 0) upsertQueries.push(supabase.from('savings_history').upsert(savRows));
    if(shRows.length > 0) upsertQueries.push(supabase.from('shopee_installments').upsert(shRows));

    var upsertResults = await Promise.all(upsertQueries);
    for (var i = 0; i < upsertResults.length; i++) {
        if (upsertResults[i].error) throw new Error("Sync upsert error: " + upsertResults[i].error.message);
    }
    
    s = gs();
    s._tombstones = { customCats: {}, recur: {}, goals: {}, wallets: {}, templates: {} };
    persistStore(s, false);
}
async function fetchRemoteData(userId) {
    if (!userId) return null;
    
    var queries = [
        supabase.from('profiles').select('*').eq('id', userId).maybeSingle(),
        supabase.from('wallets').select('*').eq('user_id', userId),
        supabase.from('categories').select('*').eq('user_id', userId),
        supabase.from('monthly_budgets').select('*').eq('user_id', userId),
        supabase.from('category_budgets').select('*').eq('user_id', userId),
        supabase.from('additional_income').select('*').eq('user_id', userId),
        supabase.from('transactions').select('*').eq('user_id', userId),
        supabase.from('savings_history').select('*').eq('user_id', userId),
        supabase.from('shopee_installments').select('*').eq('user_id', userId),
        supabase.from('recurring_expenses').select('*').eq('user_id', userId),
        supabase.from('savings_goals').select('*').eq('user_id', userId),
        supabase.from('budget_templates').select('*').eq('user_id', userId),
        supabase.from('custom_icons').select('*').eq('user_id', userId)
    ];
    
    var results = await Promise.all(queries);
    for (var i = 0; i < results.length; i++) {
        if (results[i].error) throw new Error("Pull error: " + results[i].error.message);
    }
    
    var s = gs();
    var userInfoObj = s.userInfo || { name: '', email: '', picture: '', provider: '' };
    var newStore = {
        meta: { updatedAt: Date.now(), migratedToSupabase: true },
        settings: s.settings || {},
        theme: s.theme || 'light',
        pin: s.pin || { enabled: false, hash: '', salt: '' },
        lastWallet: s.lastWallet || 'cash',
        wallets: [],
        customCats: [],
        mo: {},
        dLog: {},
        savings: { history: [] },
        shM: {},
        recur: [],
        goals: [],
        templates: [],
        customIcons: {},
        sims: s.sims || [],
        simDraft: s.simDraft || {},
        isLoggedIn: true,
        userInfo: userInfoObj,
        _tombstones: { customCats: {}, recur: {}, goals: {}, wallets: {}, templates: {} }
    };
    
    var prof = results[0].data;
    if (prof) {
        newStore.settings = {
            salary: Number(prof.salary || 0),
            savGoal: Number(prof.savings_goal || 0),
            weeklyOn: !!prof.weekly_on,
            showDecimal: !!prof.show_decimal,
            hideAmount: !!prof.hide_amount,
            lowRemaining: Number(prof.low_remaining || 1000),
            warnPercent: Number(prof.warn_percent || 90)
        };
        newStore.theme = prof.theme || 'light';
        newStore.pin = {
            enabled: !!prof.pin_enabled,
            hash: prof.pin_hash || '',
            salt: prof.pin_salt || ''
        };
        newStore.lastWallet = prof.last_wallet || 'cash';
        newStore.userInfo = {
            name: prof.display_name || userInfoObj.name || '',
            email: prof.email || userInfoObj.email || '',
            picture: prof.avatar_url || userInfoObj.picture || '',
            provider: prof.auth_provider || userInfoObj.provider || ''
        };
        if (prof.updated_at) {
            newStore.meta.updatedAt = new Date(prof.updated_at).getTime();
        }
    }
    
    newStore.wallets = (results[1].data || []).map(function(w) {
        return { id: w.id, name: w.name, type: w.type };
    });
    
    newStore.customCats = (results[2].data || []).map(function(c) {
        return { id: c.id, name: c.name, icon: c.icon, budget: Number(c.budget || 0) };
    });
    
    (results[3].data || []).forEach(function(m) {
        newStore.mo[m.month_key] = {
            sal: Number(m.salary || 0),
            savAutoTransfer: !!m.savings_auto_transfer,
            oI: []
        };
    });
    
    (results[4].data || []).forEach(function(cb) {
        if (newStore.mo[cb.month_key]) {
            newStore.mo[cb.month_key][cb.category_id] = Number(cb.budget_amount || 0);
        }
    });
    
    (results[5].data || []).forEach(function(inc) {
        if (newStore.mo[inc.month_key]) {
            newStore.mo[inc.month_key].oI.push({
                id: inc.id,
                a: Number(inc.amount || 0),
                n: inc.note || '',
                ck: inc.is_checked !== false
            });
        }
    });
    
    (results[6].data || []).forEach(function(tx) {
        if (!newStore.dLog[tx.date_key]) newStore.dLog[tx.date_key] = [];
        newStore.dLog[tx.date_key].push({
            id: tx.id,
            a: Number(tx.amount || 0),
            cat: tx.category_id,
            n: tx.note || '',
            w: tx.wallet_id,
            t: tx.time_key
        });
    });
    Object.keys(newStore.dLog).forEach(function(dk) {
        newStore.dLog[dk].sort(function(a, b) {
            return (a.t || '') < (b.t || '') ? -1 : 1;
        });
    });
    
    newStore.savings.history = (results[7].data || []).map(function(sh) {
        return {
            id: sh.id,
            type: sh.type,
            amount: Number(sh.amount || 0),
            date: sh.date,
            monthKey: sh.month_key,
            source: decodeSavingsSource(sh.source,sh.note),
            note: decodeSavingsNote(sh.note)
        };
    });
    
    (results[8].data || []).forEach(function(sh) {
        newStore.shM[sh.month_key] = Number(sh.amount || 0);
    });
    
    newStore.recur = (results[9].data || []).map(function(re) {
        return {
            id: re.id,
            name: re.name,
            amount: Number(re.amount || 0),
            cat: re.category_id,
            on: re.is_on !== false
        };
    });
    
    newStore.goals = (results[10].data || []).map(function(g) {
        return {
            id: g.id,
            name: g.name,
            target: Number(g.target_amount || 0),
            cur: Number(g.current_amount || 0)
        };
    });
    
    newStore.templates = (results[11].data || []).map(function(t) {
        return {
            id: t.id,
            name: t.name,
            snapshot: t.snapshot_data
        };
    });
    
    (results[12].data || []).forEach(function(ci) {
        newStore.customIcons[ci.icon_key] = ci.svg_content;
    });
    
    recalcSavingsBalance(newStore);
    return newStore;
}

function smartMergeStores(local, remote) {
    if (!remote) return local;
    
    var s = JSON.parse(JSON.stringify(local));
    var r = JSON.parse(JSON.stringify(remote));
    
    var localTime = s.meta ? Number(s.meta.updatedAt || 0) : 0;
    var remoteTime = r.meta ? Number(r.meta.updatedAt || 0) : 0;
    
    if (remoteTime > localTime) {
        s.settings = Object.assign({}, s.settings, r.settings);
        s.theme = r.theme || s.theme;
        s.pin = r.pin || s.pin;
        s.lastWallet = r.lastWallet || s.lastWallet;
        s.userName = r.userName || s.userName;
    }
    
    var walletMap = {};
    (r.wallets || []).forEach(function(w) { walletMap[w.id] = w; });
    (s.wallets || []).forEach(function(w) {
        if (!r._tombstones || !r._tombstones.wallets || !r._tombstones.wallets[w.id]) {
            walletMap[w.id] = w;
        }
    });
    s.wallets = Object.values(walletMap);
    
    var catMap = {};
    (r.customCats || []).forEach(function(c) { catMap[c.id] = c; });
    (s.customCats || []).forEach(function(c) {
        if (!r._tombstones || !r._tombstones.customCats || !r._tombstones.customCats[c.id]) {
            catMap[c.id] = c;
        }
    });
    s.customCats = Object.values(catMap);
    
    var txMap = {};
    Object.keys(r.dLog || {}).forEach(function(dk) {
        (r.dLog[dk] || []).forEach(function(tx) {
            txMap[tx.id] = Object.assign({ dateKey: dk }, tx);
        });
    });
    Object.keys(s.dLog || {}).forEach(function(dk) {
        (s.dLog[dk] || []).forEach(function(tx) {
            if (!tx.id) tx.id = genId('dl');
            if (!txMap[tx.id]) {
                txMap[tx.id] = Object.assign({ dateKey: dk }, tx);
            }
        });
    });
    
    s.dLog = {};
    Object.values(txMap).forEach(function(tx) {
        var dk = tx.dateKey;
        delete tx.dateKey;
        if (!s.dLog[dk]) s.dLog[dk] = [];
        s.dLog[dk].push(tx);
    });
    Object.keys(s.dLog).forEach(function(dk) {
        s.dLog[dk].sort(function(a, b) { return (a.t || '') < (b.t || '') ? -1 : 1; });
    });
    
    var savMap = {};
    ((r.savings && r.savings.history) || []).forEach(function(sh) { savMap[sh.id] = sh; });
    ((s.savings && s.savings.history) || []).forEach(function(sh) {
        if (!sh.id) sh.id = genId('sv');
        savMap[sh.id] = sh;
    });
    s.savings = { history: Object.values(savMap) };
    s.savings.history.sort(function(a, b) { return (a.date || '') < (b.date || '') ? 1 : -1; });
    
    if (!s.mo) s.mo = {};
    if (!r.mo) r.mo = {};
    var allMonthKeys = Array.from(new Set(Object.keys(s.mo).concat(Object.keys(r.mo))));
    allMonthKeys.forEach(function(k) {
        var localM = s.mo[k] || { sal: 0, savAutoTransfer: false, oI: [] };
        var remoteM = r.mo[k] || { sal: 0, savAutoTransfer: false, oI: [] };
        
        var mSal = remoteTime > localTime ? (remoteM.sal || localM.sal || 0) : (localM.sal || remoteM.sal || 0);
        var mSavAuto = remoteTime > localTime ? (remoteM.savAutoTransfer) : (localM.savAutoTransfer);
        
        var mergedM = {
            sal: mSal,
            savAutoTransfer: mSavAuto,
            oI: []
        };
        
        getBudgetKeys(localM).concat(getBudgetKeys(remoteM)).forEach(function(catId) {
            mergedM[catId] = remoteTime > localTime ? (remoteM[catId] !== undefined ? remoteM[catId] : localM[catId]) : (localM[catId] !== undefined ? localM[catId] : remoteM[catId]);
        });
        
        var incMap = {};
        (remoteM.oI || []).forEach(function(item) { incMap[item.id] = item; });
        (localM.oI || []).forEach(function(item) {
            if (!item.id) item.id = genId('inc');
            incMap[item.id] = item;
        });
        mergedM.oI = Object.values(incMap);
        
        s.mo[k] = mergedM;
    });
    
    if (!s.shM) s.shM = {};
    var shKeys = Array.from(new Set(Object.keys(s.shM).concat(Object.keys(r.shM || {}))));
    shKeys.forEach(function(k) {
        var localVal = s.shM[k];
        var remoteVal = (r.shM && r.shM[k] !== undefined) ? r.shM[k] : undefined;
        if (remoteTime > localTime) {
            s.shM[k] = remoteVal !== undefined ? Number(remoteVal || 0) : Number(localVal || 0);
        } else {
            s.shM[k] = localVal !== undefined ? Number(localVal || 0) : Number(remoteVal || 0);
        }
    });
    
    var recurMap = {};
    (r.recur || []).forEach(function(item) { recurMap[item.id] = item; });
    (s.recur || []).forEach(function(item) {
        if (!r._tombstones || !r._tombstones.recur || !r._tombstones.recur[item.id]) {
            recurMap[item.id] = item;
        }
    });
    s.recur = Object.values(recurMap);
    
    var goalMap = {};
    (r.goals || []).forEach(function(g) { goalMap[g.id] = g; });
    (s.goals || []).forEach(function(g) {
        if (!r._tombstones || !r._tombstones.goals || !r._tombstones.goals[g.id]) {
            goalMap[g.id] = g;
        }
    });
    s.goals = Object.values(goalMap);
    
    var tplMap = {};
    (r.templates || []).forEach(function(t) { tplMap[t.id] = t; });
    (s.templates || []).forEach(function(t) {
        // Only restore local template if it hasn't been tombstoned on remote
        if (!r._tombstones || !r._tombstones.templates || !r._tombstones.templates[t.id]) {
            tplMap[t.id] = t;
        }
    });
    s.templates = Object.values(tplMap);
    
    // Merge simDraft (newer wins, fallbacks to non-undefined)
    s.simDraft = remoteTime > localTime ? (r.simDraft !== undefined ? r.simDraft : s.simDraft) : (s.simDraft !== undefined ? s.simDraft : r.simDraft);
    
    // Merge saved simulations list (sims) using unique IDs and tombstones
    var simMap = {};
    (r.sims || []).forEach(function(sm) { simMap[sm.id] = sm; });
    (s.sims || []).forEach(function(sm) {
        if (!sm.id) sm.id = genId('sim');
        if (!r._tombstones || !r._tombstones.sims || !r._tombstones.sims[sm.id]) {
            simMap[sm.id] = sm;
        }
    });
    s.sims = Object.values(simMap);
    
    s.customIcons = Object.assign({}, r.customIcons, s.customIcons);
    
    recalcSavingsBalance(s);
    s.meta.updatedAt = Date.now();
    return s;
}

async function pullFromSupabaseToLocal(userId) {
    if (!userId) return;
    var remote = await fetchRemoteData(userId);
    if (!remote) return;
    persistStore(remote, false);
    applyCustomIcons();
    applyIndexSvgOverrides();
    if (remote.theme) applyTheme(remote.theme);
}

async function checkAndHandleMigration(userId) {
    var s = gs();
    if (s.meta.migratedToSupabase) {
        var remote = await fetchRemoteData(userId);
        if (remote) {
            var local = gs();
            var localTime = local.meta ? Number(local.meta.updatedAt || 0) : 0;
            var remoteTime = remote.meta ? Number(remote.meta.updatedAt || 0) : 0;
            if (localTime > remoteTime) {
                await syncLocalToSupabase(userId);
                _lastUploadTime=Date.now();
                _lastSyncSuccess=Date.now();
                _syncPending=false;
                updateSyncIndicator();
            } else if (remoteTime > localTime || _syncPending) {
                // Remote is newer OR we have cd329f3d3e55ddbcdc5485e272826d7653df873c local changes — smart merge to keep both
                console.log("Sync: merging local and remote on login...");
                var merged = smartMergeStores(local, remote);
                persistStore(merged, false);
                applyCustomIcons();
                applyIndexSvgOverrides();
                if (merged.theme) applyTheme(merged.theme);
                queueSync(true);
            } else {
                // Timestamps identical and no cd329f3d3e55ddbcdc5485e272826d7653df873c — remote wins (fresh load from another device)
                persistStore(remote, false);
                applyCustomIcons();
                applyIndexSvgOverrides();
                if (remote.theme) applyTheme(remote.theme);
            }
        }
        return;
    }
    
    var { count, error } = await supabase.from('transactions').select('*', { count: 'exact', head: true }).eq('user_id', userId);
    if (error) {
        console.error("Error checking transactions:", error);
        return;
    }
    
    var guestHasData = false;
    if (s.dLog && Object.keys(s.dLog).length > 0) guestHasData = true;
    if (s.customCats && s.customCats.length > 0) guestHasData = true;
    if (s.savings && s.savings.history && s.savings.history.length > 0) guestHasData = true;
    if (s.recur && s.recur.length > 0) guestHasData = true;
    if (s.goals && s.goals.length > 0) guestHasData = true;
    if (s.templates && s.templates.length > 0) guestHasData = true;
    if (s.shM && Object.keys(s.shM).some(function(k){return Number(s.shM[k]||0)>0})) guestHasData = true;
    if (s.mo && Object.keys(s.mo).some(function(k){
        var d = s.mo[k] || {};
        if (Number(d.sal || 0) > 0) return true;
        if ((d.oI || []).length > 0) return true;
        return getBudgetKeys(d).some(function(catId){return Number(d[catId]||0)>0});
    })) guestHasData = true;
    
    if (guestHasData && count === 0) {
        console.log("Migrating local guest data to Supabase...");
        await syncLocalToSupabase(userId);
    } else if (guestHasData && count > 0) {
        console.log("Both guest data and Supabase data exist. Smart merging...");
        var remote = await fetchRemoteData(userId);
        var merged = smartMergeStores(s, remote);
        persistStore(merged, false);
        await syncLocalToSupabase(userId);
        applyCustomIcons();
        applyIndexSvgOverrides();
        if (merged.theme) applyTheme(merged.theme);
    } else {
        console.log("Pulling data from Supabase...");
        await pullFromSupabaseToLocal(userId);
    }
    
    s = gs();
    s.meta.migratedToSupabase = true;
    persistStore(s, false);
}
function thaiSyncError(err){
    // แปลง error จาก Supabase / network เป็นข้อความภาษาไทยที่ผู้ใช้เข้าใจ
    var msg = (err && (err.message || err.error_description || err.error)) ? String(err.message || err.error_description || err.error) : String(err || '');
    var low = msg.toLowerCase();
    if(!window.navigator.onLine || low.indexOf('failed to fetch')>=0 || low.indexOf('network')>=0 || low.indexOf('networkerror')>=0)
        return 'ไม่มีการเชื่อมต่ออินเทอร์เน็ต';
    if(low.indexOf('timeout')>=0 || low.indexOf('timed out')>=0)
        return 'เชื่อมต่อเซิร์ฟเวอร์นานเกินไป (timeout)';
    if(low.indexOf('jwt')>=0 || low.indexOf('token')>=0 || low.indexOf('401')>=0 || low.indexOf('expired')>=0 || low.indexOf('unauthorized')>=0)
        return 'เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่';
    if(low.indexOf('row-level security')>=0 || low.indexOf('rls')>=0 || low.indexOf('policy')>=0 || low.indexOf('403')>=0 || low.indexOf('permission')>=0 || low.indexOf('forbidden')>=0)
        return 'ไม่มีสิทธิ์บันทึกข้อมูล (สิทธิ์การเข้าถึง)';
    if(low.indexOf('duplicate')>=0 || low.indexOf('unique')>=0 || low.indexOf('conflict')>=0 || low.indexOf('409')>=0)
        return 'ข้อมูลซ้ำซ้อนกับที่มีอยู่';
    if(low.indexOf('violates')>=0 || low.indexOf('constraint')>=0 || low.indexOf('invalid')>=0 || low.indexOf('400')>=0)
        return 'รูปแบบข้อมูลไม่ถูกต้อง';
    if(low.indexOf('429')>=0 || low.indexOf('rate')>=0 || low.indexOf('too many')>=0)
        return 'ส่งคำขอบ่อยเกินไป กรุณารอสักครู่';
    if(/50[0-9]/.test(low) || low.indexOf('server')>=0 || low.indexOf('unavailable')>=0)
        return 'เซิร์ฟเวอร์ขัดข้องชั่วคราว กรุณาลองใหม่';
    return 'บันทึกขึ้นคลาวด์ไม่สำเร็จ' + (msg ? ' (' + msg.slice(0,60) + ')' : '');
}
function showSaveBadge(state, detail){
    // state: 'saving' | 'ok' | 'error'
    var el=document.getElementById('saveBadge');
    if(!el)return;
    if(isGuest || !supabaseUserId){el.classList.remove('show');return}
    var ic, txt, cls;
    if(state==='saving'){
        cls='saving';
        ic='<svg class="sb-spin" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>';
        txt='กำลังบันทึกขึ้นคลาวด์...';
    }else if(state==='ok'){
        cls='ok';
        ic='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>';
        txt='บันทึกขึ้นคลาวด์แล้ว';
    }else{
        cls='error';
        ic='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="13"/><line x1="12" y1="16.5" x2="12" y2="16.5"/></svg>';
        txt=detail||'บันทึกไม่สำเร็จ';
    }
    el.className='save-badge show '+cls;
    el.innerHTML='<span class="sb-ic">'+ic+'</span><span class="sb-txt">'+esc(txt)+'</span>';
    clearTimeout(_saveBadgeTimer);
    if(state!=='saving'){
        // สำเร็จซ่อนเร็ว, ผิดพลาดให้ค้างนานกว่าเพื่ออ่านเหตุผล
        _saveBadgeTimer=setTimeout(function(){el.classList.remove('show')}, state==='ok'?2500:7000);
    }
}
function queueSync(immediate){
    if(!supabaseUserId) return;
    if(_syncing){_syncPending=true;return}
    clearTimeout(_syncTimer);
    if(immediate) supabaseSync();
    else _syncTimer=setTimeout(function(){supabaseSync()},1500);
}
function supabaseSync(){
    if(!supabaseUserId) return Promise.resolve();
    if(_syncing){_syncPending=true;return Promise.resolve()}
    _syncing=true;
    clearTimeout(_syncTimer);
    
    var data = gs();
    data.lastSync = new Date().toISOString();
    persistStore(data, false);
    
    showSaveBadge('saving');
    updateSyncIndicator();
    
    return syncLocalToSupabase(supabaseUserId).then(function(){
        _lastUploadTime=Date.now();
        _lastSyncSuccess=Date.now();
        _syncPending=false;
        _syncRetryDelay=0;
        _lastSyncError='';
        showSaveBadge('ok');
        updateSyncIndicator();
    }).catch(function(err){
        console.error("Supabase sync failed:", err);
        _syncPending=true;
        _lastSyncError=thaiSyncError(err);
        showSaveBadge('error', _lastSyncError);
        updateSyncIndicator();
    }).then(function(){
        _syncing=false;
        if(_syncPending && supabaseUserId){
            _syncPending=false;
            // Exponential backoff: 2s → 4s → 8s → max 30s to avoid tight retry loops
            var delay=Math.min((_syncRetryDelay||0)*2||2000,30000);
            _syncRetryDelay=delay;
            _syncTimer=setTimeout(function(){supabaseSync()},delay);
        }
    });
}
function supabasePollSync(){
    if(!supabaseUserId||_syncing)return;
    if(Date.now()-_lastUploadTime<10000)return;
    supabase.from('profiles').select('updated_at').eq('id', supabaseUserId).maybeSingle().then(function(resp){
        var prof = resp.data;
        if(!prof || !prof.updated_at) return;
        var remoteTime = new Date(prof.updated_at).getTime();
        var local = gs();
        var localTime = local.meta ? Number(local.meta.updatedAt || 0) : 0;
        if(remoteTime > localTime) {
            if (_syncPending) {
                console.log("Sync conflict detected in poll! Smart merging...");
                fetchRemoteData(supabaseUserId).then(function(remote) {
                    if (!remote) return;
                    var merged = smartMergeStores(local, remote);
                    persistStore(merged, false);
                    render();
                    queueSync(true);
                });
            } else {
                pullFromSupabaseToLocal(supabaseUserId).then(function() {
                    render();
                });
            }
        }
    }).catch(function(){});
}
function fmtSyncAge(){if(!_lastSyncSuccess)return'ยังไม่เคย sync';var s=Math.floor((Date.now()-_lastSyncSuccess)/1000);if(s<5)return'เมื่อสักครู่';if(s<60)return s+'วินาทีที่แล้ว';var m=Math.floor(s/60);if(m<60)return m+'นาทีที่แล้ว';var h=Math.floor(m/60);return h+'ชั่วโมงที่แล้ว'}
function manualSync(){
    var btn=document.getElementById('manualSyncBtn');
    var lbl=document.getElementById('manualSyncLbl');
    if(!btn||!lbl)return;
    if(isGuest){alert('ต้องเชื่อมต่อบัญชีผู้ใช้ก่อน');return}
    if(!supabaseUserId) {
        googleLogin();
        return;
    }
    if(_syncing)return;
    btn.disabled=true;
    btn.innerHTML='<span class="spin-ic"></span>กำลังซิงค์…';
    lbl.textContent='';
    
    supabase.from('profiles').select('updated_at').eq('id', supabaseUserId).maybeSingle()
        .then(function(resp){
            var prof = resp.data;
            var remoteTime = (prof && prof.updated_at) ? new Date(prof.updated_at).getTime() : 0;
            var local = gs();
            var localTime = local.meta ? Number(local.meta.updatedAt || 0) : 0;
            
            if (localTime > remoteTime) {
                console.log("Local is newer. Uploading local data to Supabase...");
                return supabaseSync();
            } else if (remoteTime > localTime) {
                console.log("Remote is newer. Merging remote data with local...");
                return fetchRemoteData(supabaseUserId).then(function(remote) {
                    if (!remote) return supabaseSync();
                    var localNow = gs();
                    var merged = smartMergeStores(localNow, remote);
                    persistStore(merged, false);
                    render();
                    return supabaseSync();
                });
            } else {
                console.log("Timestamps are identical. Forcing upload to be safe...");
                return supabaseSync();
            }
        })
        .then(function(){
            btn.disabled=false;
            btn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> ซิงค์สำเร็จ';
            btn.classList.add('sync-ok');
            lbl.textContent='sync ล่าสุด: '+fmtSyncAge();
            setTimeout(function(){btn.innerHTML='⇕ ซิงค์กับ Supabase';btn.classList.remove('sync-ok');btn.disabled=false},2500);
        }).catch(function(err){
            console.error("Manual sync failed:", err);
            _lastSyncError=thaiSyncError(err);
            showSaveBadge('error', _lastSyncError);
            btn.disabled=false;
            btn.innerHTML='✕ ไม่สามารถเชื่อมต่อได้';
            btn.classList.add('sync-err');
            setTimeout(function(){btn.innerHTML='⇕ ซิงค์กับ Supabase';btn.classList.remove('sync-err');btn.disabled=false},3000);
        });
}

async function forcePullFromCloud() {
    if (isGuest || !supabaseUserId) return;
    var btn = document.getElementById('forcePullBtn');
    if (!btn) return;
    
    if (!confirm('⚠️ คำเตือน: คุณต้องการดึงข้อมูลทั้งหมดจากระบบคลาวด์เพื่อเขียนทับข้อมูลบนเครื่องนี้ใช่หรือไม่?\n\nการกู้คืนวิธีนี้จะเขียนทับข้อมูลในเครื่องปัจจุบันของคุณทันที ข้อมูลที่ยังไม่ได้ซิงค์จากเครื่องนี้จะสูญหาย')) return;
    
    btn.disabled = true;
    var originalHTML = btn.innerHTML;
    btn.innerHTML = '<span class="spin-ic"></span>กำลังดึงข้อมูลล่าสุด...';
    
    try {
        await pullFromSupabaseToLocal(supabaseUserId);
        _lastSyncSuccess = Date.now();
        _syncPending = false;
        updateSyncIndicator();
        alert('ดึงข้อมูลล่าสุดจากระบบคลาวด์และเขียนทับเสร็จสิ้น!');
        closeUser();
        render();
    } catch(err) {
        console.error("Force pull failed:", err);
        alert('เกิดข้อผิดพลาดในการดึงข้อมูล: ' + err.message);
    } finally {
        btn.disabled = false;
        btn.innerHTML = originalHTML;
    }
}
function enterApp(){
    refreshCurrentContext();
    var app=document.getElementById('app'),wasShown=app.classList.contains('show');
    document.getElementById('welcome').classList.add('hide');
    app.classList.add('show');
    applyTheme(gs().theme||'light');
    setV(vw||'m');
    updateUserBtn();
    if(!wasShown&&pinEnabled()){showPinLock('unlock',{title:'ใส่ PIN เพื่อปลดล็อก',sub:'เพื่อความปลอดภัยของข้อมูล',len:4,autoSubmit:true,canCancel:false})}
    if(!_pollTimer)_pollTimer=setInterval(function(){supabasePollSync()},5*60*1000);
    if(!_visListenerAdded){_visListenerAdded=true;document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')setTimeout(supabasePollSync,1000)})}
}
