function closeUser(){document.getElementById('uM').classList.remove('open')}
function restoreAutoBackupSnapshot(idx) {
    try {
        var raw = localStorage.getItem('okane_auto_backups');
        if (!raw) return;
        var backups = JSON.parse(raw) || [];
        var b = backups[idx];
        if (!b) return;
        if (!confirm('⚠️ คุณแน่ใจหรือไม่ว่าต้องการกู้คืนข้อมูลไปยังจุดนี้?\n\nข้อมูลปัจจุบันของคุณบนเครื่องจะถูกเขียนทับด้วยข้อมูลสำรองของวันที่ ' + new Date(b.exportedAt).toLocaleString('th-TH'))) return;
        
        persistStore(b.data, true);
        applyCustomIcons();
        applyIndexSvgOverrides();
        if (b.data.theme) applyTheme(b.data.theme);
        
        alert('กู้คืนข้อมูลสำเร็จ!');
        closeUser();
        render();
        queueSync(true);
    } catch(e) {
        alert('เกิดข้อผิดพลาดในการกู้คืน: ' + e.message);
    }
}

function exportCsv(){
    var s=gs();
    var rows=[['วันที่','เวลา','จำนวนเงิน','หมวดหมู่','กระเป๋า','หมายเหตุ']];
    var dates=Object.keys(s.dLog||{}).sort();
    dates.forEach(function(dk){
        (s.dLog[dk]||[]).forEach(function(e){
            var note=String(e.n||'').replace(/"/g,'""');
            rows.push([dk,e.t||'',Number(e.a||0),getCatName(e.cat||'other'),getWalletName(e.w||'cash'),'"'+note+'"']);
        });
    });
    var csv='\uFEFF'+rows.map(function(r){return r.join(',')}).join('\r\n');
    var blob=new Blob([csv],{type:'text/csv;charset=utf-8'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a');a.href=url;
    a.download='okane_transactions_'+getThaiToday()+'.csv';
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function saveUser(){var s=gs();s.userName=(document.getElementById('uName')||{}).value||'';syncNow(s);render();closeUser()}
async function deleteUserSupabaseData(userId) {
    if (!userId || !supabase) return;
    try {
        await supabase.from('transactions').delete().eq('user_id', userId);
        await supabase.from('savings_history').delete().eq('user_id', userId);
        await supabase.from('shopee_installments').delete().eq('user_id', userId);
        await supabase.from('recurring_expenses').delete().eq('user_id', userId);
        await supabase.from('savings_goals').delete().eq('user_id', userId);
        await supabase.from('budget_templates').delete().eq('user_id', userId);
        await supabase.from('custom_icons').delete().eq('user_id', userId);
        await supabase.from('category_budgets').delete().eq('user_id', userId);
        await supabase.from('additional_income').delete().eq('user_id', userId);
        await supabase.from('monthly_budgets').delete().eq('user_id', userId);
        await supabase.from('categories').delete().eq('user_id', userId);
        await supabase.from('wallets').delete().eq('user_id', userId);
        await supabase.from('profiles').delete().eq('id', userId);
    } catch (e) {
        console.error("Failed to delete user supabase data:", e);
    }
}
function logout(){
    if(_syncPending) {
        if(!confirm('⚠️ ยังมีข้อมูลที่แก้ไขล่าสุดแต่ยังไม่ได้ซิงค์ขึ้นระบบคลาวด์สำเร็จ\n\nหากคุณออกจากระบบตอนนี้ ข้อมูลล่าสุดอาจสูญหายจากเครื่องนี้ได้\n\nต้องการออกจากระบบจริงๆ หรือไม่?')) return;
    } else {
        if(!confirm('คุณต้องการออกจากระบบ Okane Wallet หรือไม่?\n(ข้อมูลของคุณบนระบบคลาวด์จะยังคงปลอดภัยอยู่เสมอ)')) return;
    }
    clearTimeout(_syncTimer);
    localStorage.removeItem('okane_v3');
    localStorage.removeItem('okane_auto_backups');
    localStorage.removeItem('okane_cat_hints');
    clearCalcCache();
    supabaseUserId = null;
    isGuest = true;
    if (supabase) {
        supabase.auth.signOut().then(function() {
            location.reload();
        }).catch(function() {
            location.reload();
        });
    } else {
        location.reload();
    }
}
function resetAll(){
    if(!confirm('\u0E25\u0E1A\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u0E17\u0E31\u0E49\u0E07\u0E2B\u0E21\u0E14?\n\n\u0E01\u0E32\u0E23\u0E01\u0E23\u0E30\u0E17\u0E33\u0E19\u0E35\u0E49\u0E44\u0E21\u0E48\u0E2A\u0E32\u0E21\u0E32\u0E23\u0E16\u0E22\u0E01\u0E40\u0E25\u0E34\u0E01\u0E44\u0E14\u0E49 \u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u0E17\u0E38\u0E01\u0E2D\u0E22\u0E48\u0E32\u0E07\u0E08\u0E30\u0E2B\u0E32\u0E22\u0E44\u0E1B\u0E16\u0E32\u0E27\u0E23'))return;
    clearTimeout(_syncTimer);
    localStorage.removeItem('okane_v3');
    localStorage.removeItem('okane_auto_backups');
    localStorage.removeItem('okane_cat_hints');
    clearCalcCache();
    var done=function(){
        supabaseUserId = null;
        isGuest=false;
        location.reload();
    };
    if(!isGuest && supabaseUserId && supabase){
        deleteUserSupabaseData(supabaseUserId).then(function(){
            supabase.auth.signOut().then(done).catch(done);
        }).catch(done);
    } else {
        done();
    }
}

function triggerPicUpload(){var f=document.getElementById('picFile');if(f)f.click()}
function handlePicUpload(){
    var file=(document.getElementById('picFile')||{}).files;
    if(!file||!file[0])return;
    var reader=new FileReader();
    reader.onload=function(e){
        var img=new Image();
        img.onload=function(){
            var canvas=document.createElement('canvas');
            canvas.width=200;canvas.height=200;
            var ctx=canvas.getContext('2d');
            var s2=Math.min(img.width,img.height);
            ctx.drawImage(img,(img.width-s2)/2,(img.height-s2)/2,s2,s2,0,0,200,200);
            var dataUrl=canvas.toDataURL('image/jpeg',0.82);
            var st=gs();st.customPicture=dataUrl;syncNow(st);
            var wrap=document.querySelector('.prof-av-wrap');
            if(wrap){var old=wrap.querySelector('img,.prof-av-empty');if(old)wrap.removeChild(old);var ni=document.createElement('img');ni.src=dataUrl;ni.className='prof-av';wrap.insertBefore(ni,wrap.firstChild)}
            updateUserBtn();
        };
        img.src=e.target.result;
    };
    reader.readAsDataURL(file[0]);
}
