function toggleDecimal(){var s=gs();var st=ensureSettings();st.showDecimal=!(st.showDecimal!==undefined?st.showDecimal:true);s.settings=st;syncNow(s);renderSettings();render()}
function toggleHideAmt(){var s=gs();var st=ensureSettings();st.hideAmount=!st.hideAmount;s.settings=st;syncNow(s);renderSettings();render()}
function openSettingsPage(p){stPage=p;renderSettings()}
function backSettings(){stPage='main';renderSettings()}
function toggleWeekly(){var s=gs();var st=ensureSettings();st.weeklyOn=!st.weeklyOn;s.settings=st;syncNow(s);renderSettings();render()}
function saveAlertSettings(){var s=gs();var st=ensureSettings();st.lowRemaining=Number(document.getElementById('stLowRem').value)||0;st.warnPercent=Number(document.getElementById('stWarnPct').value)||90;s.settings=st;syncNow(s);renderSettings();render()}
function saveCardSettings(){var s=gs();var st=ensureSettings();st.card={cycleDay:Math.min(28,Math.max(1,Number(document.getElementById('stCycle').value)||25)),dueDay:Math.min(28,Math.max(1,Number(document.getElementById('stDue').value)||10))};s.settings=st;syncNow(s);renderSettings();render()}
function togglePin(){var cfg=getPinCfg();if(cfg.enabled){showPinLock('disable',{title:'ปิด PIN',sub:'ใส่ PIN เพื่อยืนยัน',len:4,autoSubmit:true,canCancel:false});return}showPinLock('set',{title:'ตั้ง PIN',sub:'ใส่ PIN 4 หลัก',len:4,autoSubmit:true,canCancel:false})}
function changePin(){var cfg=getPinCfg();if(!cfg.enabled)return;showPinLock('change_old',{title:'เปลี่ยน PIN',sub:'ใส่ PIN ปัจจุบัน',len:4,autoSubmit:true,canCancel:false})}
function disablePin(){var cfg=getPinCfg();if(!cfg.enabled)return;showPinLock('disable',{title:'ปิด PIN',sub:'ใส่ PIN เพื่อยืนยัน',len:4,autoSubmit:true,canCancel:false})}

function getRecurring(){var s=gs();if(!s.recur)s.recur=[];return s.recur}
function renderSettingsRecurring(){var s=gs();var items=getRecurring();var cats=getAllDailyCats();var h='<div style="padding:12px 0"><div class="cal-hd" style="margin:0 0 10px"><button onclick="backSettings()"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="15 18 9 12 15 6"/></svg></button><span>รายการประจำ</span><div style="width:30px"></div></div>';h+='<div style="font-size:11px;color:var(--tx3);margin-bottom:10px">เพิ่มรายการที่เกิดทุกเดือน เช่น เน็ต สมาชิกรายเดือน หรือค่าผ่อน</div>';if(items.length>0){items.forEach(function(it){h+='<div class="sr"><div class="sl">'+esc(it.name||'-')+'<small>'+esc(getCatName(it.cat||'other'))+' • '+fmt(it.amount||0)+'</small></div><button class="tgl'+(it.on?' on':'')+'" onclick="togRecur(\''+it.id+'\')"></button><button class="cd" onclick="delRecur(\''+it.id+'\')">'+IC.dl+'</button></div>'})}else{h+='<div class="dl-empty" style="padding:18px 0">ยังไม่มีรายการประจำ</div>'}h+='<div class="prof-sec-t">เพิ่มรายการ</div>';h+='<div class="ar" style="padding:0"><input class="inp" id="rcName" placeholder="ชื่อรายการ"><input class="inp" type="number" id="rcAmt" placeholder="จำนวนเงิน" min="0" style="flex:.6"></div>';h+='<div class="ar" style="padding:8px 0 0"><select class="inp" id="rcCat" style="appearance:auto"><option value="other">อื่นๆ</option>'+cats.filter(function(c){return c.id!=='other'}).map(function(c){return '<option value="'+c.id+'">'+esc(c.name)+'</option>'}).join('')+'</select><button class="btn btn-ac" style="padding:8px 12px" onclick="addRecur()">เพิ่ม</button></div>';h+='</div>';return h}
function addRecur(){var name=(document.getElementById('rcName').value||'').trim();var amt=Number(document.getElementById('rcAmt').value)||0;var cat=document.getElementById('rcCat').value||'other';if(!name||amt<=0)return;var s=gs();if(!s.recur)s.recur=[];var now=getBangkokNow();s.recur.push({id:genId('rc'),name:name,amount:amt,cat:cat,on:true,startKey:mk(now.getFullYear(),now.getMonth())});syncNow(s);renderSettings()}
function togRecur(id){var s=gs();if(!s.recur)return;var it=s.recur.find(function(x){return x.id===id});if(!it)return;it.on=!it.on;syncNow(s);renderSettings();render()}
function delRecur(id){var s=gs();if(!s.recur)return;s.recur=s.recur.filter(function(x){return x.id!==id});addTombstone(s,'recur',id);syncNow(s);renderSettings();render()}

function getGoals(){var s=gs();if(!s.goals)s.goals=[];return s.goals}
function renderSettingsGoals(){var s=gs();var g=getGoals();var h='<div style="padding:12px 0"><div class="cal-hd" style="margin:0 0 10px"><button onclick="backSettings()"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="15 18 9 12 15 6"/></svg></button><span>Goals</span><div style="width:30px"></div></div>';if(g.length>0){g.forEach(function(it){var pct=it.target>0?Math.min((Number(it.cur||0)/Number(it.target||0))*100,100):0;h+='<div class="sec" style="margin:0 0 12px"><div class="sec-t"><span>'+esc(it.name||'-')+'</span><span style="font-family:var(--font-sans);font-size:11px;color:var(--tx3)">'+pct.toFixed(0)+'%</span></div><div class="sc"><div style="display:flex;justify-content:space-between;padding:4px 16px 10px"><span style="font-size:12px;color:var(--tx3)">'+fmt(it.cur||0)+' / '+fmt(it.target||0)+'</span><button class="cd" onclick="delGoal(\''+it.id+'\')">'+IC.dl+'</button></div><div class="prog-wrap"><div class="prog-bar"><div class="prog-fill pf-gn" style="width:'+pct+'%"></div></div></div><div class="ar" style="padding:10px 16px 0"><input class="inp" type="number" id="gAdd_'+it.id+'" placeholder="เพิ่มยอด" min="0"><button class="btn btn-ac" style="padding:8px 12px" onclick="addGoalAmt(\''+it.id+'\')">เพิ่ม</button></div></div></div>'})}else{h+='<div class="dl-empty" style="padding:18px 0">ยังไม่มี Goals</div>'}h+='<div class="prof-sec-t">สร้าง Goal</div>';h+='<div class="ar" style="padding:0"><input class="inp" id="gName" placeholder="ชื่อเป้าหมาย"><input class="inp" type="number" id="gTarget" placeholder="เป้าหมาย" min="0" style="flex:.6"></div>';h+='<div style="margin-top:10px"><button class="btn btn-ac btn-full" onclick="addGoal()">เพิ่ม Goal</button></div>';h+='</div>';return h}
function addGoal(){var name=(document.getElementById('gName').value||'').trim();var tgt=Number(document.getElementById('gTarget').value)||0;if(!name||tgt<=0)return;var s=gs();if(!s.goals)s.goals=[];s.goals.push({id:genId('g'),name:name,target:tgt,cur:0});syncNow(s);renderSettings();render()}
function addGoalAmt(id){var inp=document.getElementById('gAdd_'+id);if(!inp)return;var a=Number(inp.value)||0;if(a<=0)return;var s=gs();if(!s.goals)return;var it=s.goals.find(function(x){return x.id===id});if(!it)return;it.cur=Number(it.cur||0)+a;syncNow(s);renderSettings();render()}
function delGoal(id){var s=gs();if(!s.goals)return;s.goals=s.goals.filter(function(x){return x.id!==id});addTombstone(s,'goals',id);syncNow(s);renderSettings();render()}

function renderSettingsWallets(){var s=gs();var w=getWallets();var h='<div style="padding:12px 0"><div class="cal-hd" style="margin:0 0 10px"><button onclick="backSettings()"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="15 18 9 12 15 6"/></svg></button><span>กระเป๋า</span><div style="width:30px"></div></div>';w.forEach(function(x){h+='<div class="sr"><div class="sl">'+esc(x.name)+'<small>'+esc(x.type)+'</small></div><button class="cd" onclick="delWallet(\''+x.id+'\')">'+IC.dl+'</button></div>'});h+='<div class="prof-sec-t">เพิ่มกระเป๋า</div>';h+='<div class="ar" style="padding:0"><input class="inp" id="wName" placeholder="ชื่อกระเป๋า"><select class="inp" id="wType" style="appearance:auto;flex:.7"><option value="cash">cash</option><option value="bank">bank</option><option value="card">card</option></select></div>';h+='<div style="margin-top:10px"><button class="btn btn-ac btn-full" onclick="addWallet()">เพิ่ม</button></div>';h+='</div>';return h}
function addWallet(){var name=(document.getElementById('wName').value||'').trim();var type=document.getElementById('wType').value||'cash';if(!name)return;var s=gs();if(!s.wallets)s.wallets=[];var id=genId('w');s.wallets.push({id:id,name:name,type:type});syncNow(s);renderSettings();render()}
function delWallet(id){
    var s=gs();
    if(!s.wallets)return;
    // Warn if any transactions still reference this wallet
    var hasOrphans=false;
    if(s.dLog){Object.keys(s.dLog).forEach(function(dk){if((s.dLog[dk]||[]).some(function(x){return x.w===id}))hasOrphans=true;})}
    if(hasOrphans&&!confirm('กระเป๋านี้ยังมีรายการค่าใช้จ่ายที่อ้างถึงอยู่\nหากลบ กระเป๋าจะถูกลบ แต่รายการเดิมจะยังคงอยู่\nต้องการดำเนินการต่อหรือไม่?'))return;
    s.wallets=s.wallets.filter(function(x){return x.id!==id});
    addTombstone(s,'wallets',id);
    syncNow(s);
    renderSettings();
    render();
}

function renderSettingsTemplates(){var s=gs();if(!s.templates)s.templates=[];var t=s.templates;var h='<div style="padding:12px 0"><div class="cal-hd" style="margin:0 0 10px"><button onclick="backSettings()"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="15 18 9 12 15 6"/></svg></button><span>Template งบ</span><div style="width:30px"></div></div>';if(t.length>0){t.forEach(function(x){h+='<div class="sr"><div class="sl">'+esc(x.name)+'<small>'+esc(x.id)+'</small></div><button class="btn btn-gh" style="padding:6px 10px;font-size:11px" onclick="applyTemplate(\''+x.id+'\')">ใช้</button><button class="cd" onclick="delTemplate(\''+x.id+'\')">'+IC.dl+'</button></div>'})}else{h+='<div class="dl-empty" style="padding:18px 0">ยังไม่มี Template</div>'}h+='<div class="prof-sec-t">สร้าง Template จากเดือนนี้</div>';h+='<div class="ar" style="padding:0"><input class="inp" id="tName" placeholder="ชื่อ Template"><button class="btn btn-ac" style="padding:8px 12px" onclick="saveTemplate()">บันทึก</button></div>';h+='</div>';return h}
function saveTemplate(){var name=(document.getElementById('tName').value||'').trim();if(!name)return;var d=gm(cY,sM_);var data=JSON.parse(JSON.stringify(d));var s=gs();if(!s.templates)s.templates=[];s.templates.push({id:genId('tpl'),name:name,data:data});syncNow(s);renderSettings()}
function applyTemplate(id){var s=gs();if(!s.templates)return;var t=s.templates.find(function(x){return x.id===id});if(!t)return;if(!confirm('ใช้ Template นี้กับเดือนนี้?'))return;var d=gm(cY,sM_);var merged=Object.assign({},d,t.data||{});sm_(cY,sM_,merged);render();renderSettings()}
function delTemplate(id){var s=gs();if(!s.templates)return;s.templates=s.templates.filter(function(x){return x.id!==id});addTombstone(s,'templates',id);syncNow(s);renderSettings()}

/* ===== STREAK TRACKING ===== */
function getStreak(){var s=gs();return s.streak||{current:0,best:0,lastDate:''}}
function updateStreakForDate(dateKey){
    if(!dateKey)return;
    var s=gs();
    if(!s.streak)s.streak={current:0,best:0,lastDate:''};
    var last=s.streak.lastDate||'';
    if(last===dateKey||last>dateKey)return;
    var prev=new Date(dateKey+'T00:00:00');
    prev.setDate(prev.getDate()-1);
    var yesterday=dKey(prev);
    s.streak.current=last===yesterday?Number(s.streak.current||0)+1:1;
    s.streak.lastDate=dateKey;
    if(s.streak.current>Number(s.streak.best||0))s.streak.best=s.streak.current;
    syncNow(s);
    if([3,7,14,30,60,100].indexOf(s.streak.current)>=0)showStreakToast(s.streak.current)
}
function showStreakToast(days){
    var el=document.getElementById('streakToast');
    if(!el)return;
    el.textContent='บันทึกครบ '+days+' วันต่อเนื่อง';
    el.classList.add('show');
    setTimeout(function(){el.classList.remove('show')},3500)
}

/* ===== INIT ===== */
document.addEventListener('input',function(e){
    var t=e.target;
    if(!(t instanceof HTMLInputElement))return;
    if(t.id==='pinInput'||t.type==='number'||t.classList.contains('edit-val')||t.classList.contains('si'))guardNumericInput(t)
});
document.addEventListener('keydown',function(e){
    var t=e.target;
    if(!(t instanceof HTMLInputElement))return;
    if(!(t.id==='pinInput'||t.type==='number'||t.classList.contains('edit-val')||t.classList.contains('si')))return;
    if(['e','E','+','-'].indexOf(e.key)>=0)e.preventDefault()
});
window.addEventListener('load',function(){
    finalizePendingUpdateState();
    clearUpdateInProgress();
    scheduleUpdateChecks();
    initGlobalCMS().then(function(){
        var t=window.OkaneCMS&&OkaneCMS.data.meta&&OkaneCMS.data.meta.default_theme;
        if(t&&typeof applyTheme==='function')applyTheme(t)
    }).finally(function(){
        refreshGlobalVisuals()
    });
    try{initSupabaseAuth()}catch(e){}
    enhanceNumericInputs(document);
    try{new MutationObserver(function(){enhanceNumericInputs(document)}).observe(document.body,{childList:true,subtree:true})}catch(e){}
    if(!window._cmsPollTimer&&supabase){
        window._cmsPollTimer=setInterval(function(){
            if(!window.OkaneCMS||!supabase)return;
            OkaneCMS.loadGlobalCMS(supabase).then(function(){refreshGlobalVisuals()});
        },5*60*1000)
    }
});
window.addEventListener('storage',function(e){
    if(e.key==='okane_v3'||e.key==='okane_global_cms')refreshGlobalVisuals();
});

/* ===== UX ENHANCEMENTS (Sprint 1) ===== */
/* Animated number tweening */
window._tweens = window._tweens || {};
function tweenEl(el){
    var key = el.getAttribute('data-tween-key');
    var target = Number(el.getAttribute('data-tween-target'));
    if(!isFinite(target))return;
    var prev = window._tweens[key];
    window._tweens[key] = target;
    if(prev===undefined||prev===target||!isFinite(prev))return;
    var fmtMode = el.getAttribute('data-tween-fmt')||'plain';
    var dur=420, t0=performance.now();
    function disp(v){
        if(fmtMode==='signed')return (v>=0?'':'-')+fmt(Math.abs(v));
        if(fmtMode==='plus')return '+'+fmt(v);
        if(fmtMode==='minus')return '-'+fmt(v);
        if(fmtMode==='short')return fmtSh(v);
        return fmt(v);
    }
    function step(now){
        var p=Math.min(1,(now-t0)/dur);
        var eased=1-Math.pow(1-p,3);
        var v=prev+(target-prev)*eased;
        el.textContent = disp(v);
        if(p<1)requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
}
function applyTweens(root){
    try{(root||document).querySelectorAll('[data-tween-key]').forEach(tweenEl)}catch(e){}
}

/* Swipe-to-delete on .dl-item rows */
function attachSwipe(root){
    try{(root||document).querySelectorAll('.dl-item:not([data-swipe-init])').forEach(function(item){
        item.setAttribute('data-swipe-init','1');
        var startX=0,startY=0,dx=0,dy=0,dragging=false,locked=false,horiz=false;
        item.addEventListener('pointerdown',function(e){
            if(e.target.closest('button,input,select,a,textarea'))return;
            startX=e.clientX;startY=e.clientY;dx=0;dy=0;dragging=true;locked=false;horiz=false;
            item.style.transition='none';
        });
        item.addEventListener('pointermove',function(e){
            if(!dragging)return;
            dx=e.clientX-startX;dy=e.clientY-startY;
            if(!horiz&&!locked){
                if(Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy)){horiz=true;locked=true;try{item.setPointerCapture(e.pointerId)}catch(_){}}
                else if(Math.abs(dy)>10){dragging=false;item.style.transform='';item.style.transition='';return}
            }
            if(horiz&&dx<0){
                var amt=Math.max(dx,-140);
                item.style.transform='translateX('+amt+'px)';
                item.classList.toggle('swipe-armed',dx<-80);
                e.preventDefault();
            }else if(horiz){
                item.style.transform='';
                item.classList.remove('swipe-armed');
            }
        });
        function end(){
            if(!dragging)return;
            dragging=false;
            item.style.transition='transform .28s cubic-bezier(.2,.8,.2,1)';
            var armed=dx<-80;
            if(armed){
                var btn=item.querySelector('.cd');
                item.style.transform='translateX(-110%)';
                item.classList.remove('swipe-armed');
                setTimeout(function(){if(btn)btn.click()},240);
            }else{
                item.style.transform='';
                item.classList.remove('swipe-armed');
            }
            if(locked){
                var supp=function(ev){ev.stopPropagation();ev.preventDefault()};
                item.addEventListener('click',supp,true);
                setTimeout(function(){item.removeEventListener('click',supp,true)},350);
            }
        }
        item.addEventListener('pointerup',end);
        item.addEventListener('pointercancel',end);
        item.addEventListener('pointerleave',function(){if(dragging)end()});
    })}catch(e){}
}

/* Smart category prediction from note keywords */
function getCatHints(){try{return JSON.parse(localStorage.getItem('okane_cat_hints')||'{}')}catch(e){return{}}}
function learnCatHint(note,catId){
    if(!note||!catId||catId==='other')return;
    var hints=getCatHints();
    var words=String(note).toLowerCase().trim().split(/\s+/).filter(function(w){return w.length>=2});
    words.forEach(function(w){
        if(!hints[w])hints[w]={};
        hints[w][catId]=(hints[w][catId]||0)+1;
    });
    try{localStorage.setItem('okane_cat_hints',JSON.stringify(hints))}catch(e){}
}
function predictCatFromNote(note){
    if(!note)return null;
    var hints=getCatHints();
    var words=String(note).toLowerCase().trim().split(/\s+/);
    var scores={};
    words.forEach(function(w){
        var h=hints[w];if(!h)return;
        Object.keys(h).forEach(function(k){scores[k]=(scores[k]||0)+h[k]});
    });
    var best=null,bestScore=0;
    Object.keys(scores).forEach(function(k){if(scores[k]>bestScore){best=k;bestScore=scores[k]}});
    return best;
}
function qaNoteChange(){
    var ni=document.getElementById('qaNote');
    window._qaN=ni?ni.value:'';
    var pred=qaCat?null:predictCatFromNote(window._qaN);
    document.querySelectorAll('.qa-cat[data-cat]').forEach(function(el){
        el.classList.toggle('suggested',!!pred&&el.getAttribute('data-cat')===pred);
    });
}

/* Reusable empty state HTML */
function emptyStateH(opts){
    opts=opts||{};
    var ic=opts.icon||'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/></svg>';
    var h='<div class="empty-state">';
    h+='<div class="empty-state-ic">'+ic+'</div>';
    if(opts.title)h+='<div class="empty-state-t">'+esc(opts.title)+'</div>';
    if(opts.desc)h+='<div class="empty-state-s">'+esc(opts.desc)+'</div>';
    if(opts.cta)h+='<button class="btn btn-ac empty-state-cta" onclick="'+opts.cta.onclick+'">'+esc(opts.cta.text)+'</button>';
    h+='</div>';
    return h;
}

/* Hook tween + swipe to render passes */
(function(){
    var origRender=window.render;
    if(typeof origRender==='function'){
        window.render=function(){
            origRender.apply(this,arguments);
            requestAnimationFrame(function(){applyTweens(document);attachSwipe(document)});
        }
    }
    var origRDL=window.rDailyList;
    if(typeof origRDL==='function'){
        window.rDailyList=function(){
            origRDL.apply(this,arguments);
            requestAnimationFrame(function(){attachSwipe(document)});
        }
    }
})();
